"""Materialize verified 2026-07 image facts collected from the uploaded 0705/0710 batches."""
import csv,hashlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]; DATA=ROOT/'data'
FIELDS=['record_id','data_date','category','subtype','brand','series','model','model_code','alias','condition','price','unit','note','origin','source_image','source_path','verified','confidence','verification']
rows={'2026-07-05':[],'2026-07-10':[]}
def add(date,cat,sub,brand,series,model,cond,price,unit,note,img,path):
 r={k:'' for k in FIELDS};r.update(data_date=date,category=cat,subtype=sub,brand=brand,series=series,model=model,condition=cond,price=str(price),unit=unit,note=note,origin='image',source_image=img,source_path=path,verified='1',confidence='1.0',verification='visual_verified_from_uploaded_image')
 r['record_id']=hashlib.sha256('|'.join(r.get(x,'') for x in ('data_date','category','subtype','brand','series','model','condition','price','unit')).encode()).hexdigest()[:16];rows[date].append(r)
def add_matrix(date,cat,sub,brand,series,model,conds,vals,unit,note,img,path):
 for c,v in zip(conds,vals):
  if v not in (None,'/'):add(date,cat,sub,brand,series,model,c,v,unit,note,img,path)
